package com.jobportal;
import com.jobportal.entity.User;import com.jobportal.repository.UserRepository;import com.jobportal.security.JwtService;import com.jobportal.service.AuthService;import com.jobportal.dto.AuthDtos.*;import org.junit.jupiter.api.Test;import org.mockito.Mockito;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;
class AuthServiceTest{@Test void rejectsDuplicateEmail(){var repo=Mockito.mock(UserRepository.class);Mockito.when(repo.existsByEmail(anyString())).thenReturn(true);var s=new AuthService(repo,new BCryptPasswordEncoder(),new JwtService("abcdefghijklmnopqrstuvwxyz1234567890",86400000));assertThrows(Exception.class,()->s.register(new RegisterRequest("A","a@a.com","password",null)));}}
